package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StringUtils.containsAny(CharSequence cs, char[] searchChars)
 * targeting maximum branch and line coverage.
 */
public class StringUtils_containsAny_TriageGen1Test {

    @Test
    public void testContainsAny_NullCharSequence() {
        assertFalse("Should return false if cs is null", 
            StringUtils.containsAny(null, new char[]{'a', 'b'}));
    }

    @Test
    public void testContainsAny_EmptyCharSequence() {
        assertFalse("Should return false if cs is empty", 
            StringUtils.containsAny("", new char[]{'a', 'b'}));
    }

    @Test
    public void testContainsAny_NullSearchChars() {
        assertFalse("Should return false if searchChars is null", 
            StringUtils.containsAny("abc", null));
    }

    @Test
    public void testContainsAny_EmptySearchChars() {
        assertFalse("Should return false if searchChars is empty", 
            StringUtils.containsAny("abc", new char[]{}));
    }

    @Test
    public void testContainsAny_NoMatch() {
        assertFalse("Should return false if no characters match", 
            StringUtils.containsAny("abc", new char[]{'x', 'y', 'z'}));
    }

    @Test
    public void testContainsAny_SingleMatchFirstChar() {
        assertTrue("Should return true if first char of cs matches", 
            StringUtils.containsAny("abc", new char[]{'a', 'b'}));
    }

    @Test
    public void testContainsAny_SingleMatchLastChar() {
        assertTrue("Should return true if last char of cs matches", 
            StringUtils.containsAny("abc", new char[]{'c'}));
    }

    @Test
    public void testContainsAny_SingleMatchMiddleChar() {
        assertTrue("Should return true if middle char of cs matches", 
            StringUtils.containsAny("abc", new char[]{'b'}));
    }

    @Test
    public void testContainsAny_MultipleMatches() {
        assertTrue("Should return true if multiple characters match", 
            StringUtils.containsAny("abcdef", new char[]{'b', 'e'}));
    }

    @Test
    public void testContainsAny_SearchCharArrayLargerThanCs() {
        assertTrue("Should return true even if searchChars is larger than cs", 
            StringUtils.containsAny("a", new char[]{'z', 'y', 'a', 'x'}));
    }

    @Test
    public void testContainsAny_WithWhitespace() {
        assertTrue("Should handle whitespace characters", 
            StringUtils.containsAny("hello world", new char[]{' '}));
        assertFalse("Should return false if whitespace not in searchChars", 
            StringUtils.containsAny("hello", new char[]{' '}));
    }

    @Test
    public void testContainsAny_SupplementaryCharacters() {
        // Testing the logic for char-based comparison
        // Note: Java chars are UTF-16 code units. 
        // The loop compares char by char.
        char highSurrogate = '\uD83D';
        char lowSurrogate = '\uDE00';
        String emoji = new String(new char[]{highSurrogate, lowSurrogate}); // 😀

        assertTrue("Should find high surrogate", 
            StringUtils.containsAny(emoji, new char[]{highSurrogate}));
        assertTrue("Should find low surrogate", 
            StringUtils.containsAny(emoji, new char[]{lowSurrogate}));
        assertFalse("Should not find unrelated char", 
            StringUtils.containsAny(emoji, new char[]{'a'}));
    }
}
